#include <bits/stdc++.h>
using namespace std;const int MOD=1000000007;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int n;cin>>n;vector<long long>p(n);for(int i=0;i<n;i++){cin>>p[i];if(i)p[i]+=p[i-1];}long long S=p.back();if(S==0){int z=0;for(int i=0;i+1<n;i++)z+=p[i]==0;long long ans=1,b=2;while(z){if(z&1)ans=ans*b%MOD;b=b*b%MOD;z>>=1;}cout<<ans<<'\n';continue;}unordered_map<long long,vector<int>>pos;pos.reserve(n*2);for(int i=0;i+1<n;i++)pos[p[i]].push_back(i);long long ans=1;for(int k=2;k<=n;k++)if(S%k==0){vector<int>prev={-1};vector<int>ways={1};bool ok=1;long long step=S/k;for(int j=1;j<k;j++){auto it=pos.find(step*j);if(it==pos.end()){ok=0;break;}auto &cur=it->second;vector<int>nw(cur.size());long long acc=0;size_t u=0;for(size_t v=0;v<cur.size();v++){while(u<prev.size()&&prev[u]<cur[v]){acc+=ways[u++];if(acc>=MOD)acc-=MOD;}nw[v]=acc;}prev=cur;ways.swap(nw);}if(ok)for(int x:ways){ans+=x;if(ans>=MOD)ans-=MOD;}}cout<<ans<<'\n';}}
